// Web Audio engine: synthesized engine voices, tire/scrape/wind loops and
// positional one-shot effects generated by synth.ts.

import * as THREE from 'three';
import { SFX, noiseLoop } from './synth.ts';
import type { EngineDef } from '../sim/vehicle/defs.ts';

export class AudioEngine {
  ctx: AudioContext | null = null;
  private master!: GainNode;
  private sfxBus!: GainNode;
  private engineBus!: GainNode;
  private ambientBus!: GainNode;
  private buffers = new Map<string, AudioBuffer[]>();
  private noise: Record<string, AudioBuffer> = {};
  private active = 0;
  volume = 0.8;
  muted = false;
  private wind: { src: AudioBufferSourceNode; filter: BiquadFilterNode; gain: GainNode } | null = null;
  private lastPlay = new Map<string, number>();
  ready = false;

  /** Must be called from a user gesture. */
  init(): void {
    if (this.ctx) {
      this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (!AC) return;
    let ctx: AudioContext;
    try {
      ctx = new AC({ latencyHint: 'interactive' });
    } catch {
      return;
    }
    this.ctx = ctx;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 12;
    comp.ratio.value = 6;
    comp.attack.value = 0.003;
    comp.release.value = 0.2;
    this.master = ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(comp);
    comp.connect(ctx.destination);
    this.sfxBus = ctx.createGain();
    this.sfxBus.connect(this.master);
    this.engineBus = ctx.createGain();
    this.engineBus.gain.value = 0.55;
    this.engineBus.connect(this.master);
    this.ambientBus = ctx.createGain();
    this.ambientBus.gain.value = 0.6;
    this.ambientBus.connect(this.master);
    const sr = ctx.sampleRate;
    // synthesize effects (spread over a few frames would be nicer; it's ~100 ms total)
    let seed = 1;
    for (const [name, def] of Object.entries(SFX)) {
      const list: AudioBuffer[] = [];
      for (let v = 0; v < def.variants; v++) {
        const data = def.fn(sr, seed++ * 7919);
        const b = ctx.createBuffer(1, data.length, sr);
        b.copyToChannel(data as Float32Array<ArrayBuffer>, 0);
        list.push(b);
      }
      this.buffers.set(name, list);
    }
    for (const c of ['white', 'pink', 'brown'] as const) {
      const d = noiseLoop(sr, 3, c, c.length * 17);
      const b = ctx.createBuffer(1, d.length, sr);
      b.copyToChannel(d as Float32Array<ArrayBuffer>, 0);
      this.noise[c] = b;
    }
    // wind
    const src = ctx.createBufferSource();
    src.buffer = this.noise.pink;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.frequency.value = 500;
    f.Q.value = 0.7;
    const g = ctx.createGain();
    g.gain.value = 0;
    src.connect(f).connect(g).connect(this.ambientBus);
    src.start();
    this.wind = { src, filter: f, gain: g };
    this.ready = true;
  }

  setVolume(v: number): void {
    this.volume = v;
    if (this.master) this.master.gain.setTargetAtTime(this.muted ? 0 : v, this.ctx!.currentTime, 0.05);
  }

  setMuted(m: boolean): void {
    this.muted = m;
    this.setVolume(this.volume);
  }

  noiseBuffer(c: 'white' | 'pink' | 'brown'): AudioBuffer | null {
    return this.noise[c] ?? null;
  }

  get engineOut(): GainNode | null {
    return this.ready ? this.engineBus : null;
  }

  get sfxOut(): GainNode | null {
    return this.ready ? this.sfxBus : null;
  }

  updateListener(cam: THREE.Camera): void {
    if (!this.ctx) return;
    const l = this.ctx.listener;
    const p = cam.position;
    const fwd = new THREE.Vector3(0, 0, -1).applyQuaternion(cam.quaternion);
    const up = new THREE.Vector3(0, 1, 0).applyQuaternion(cam.quaternion);
    const t = this.ctx.currentTime;
    if (l.positionX) {
      l.positionX.setTargetAtTime(p.x, t, 0.02);
      l.positionY.setTargetAtTime(p.y, t, 0.02);
      l.positionZ.setTargetAtTime(p.z, t, 0.02);
      l.forwardX.setTargetAtTime(fwd.x, t, 0.02);
      l.forwardY.setTargetAtTime(fwd.y, t, 0.02);
      l.forwardZ.setTargetAtTime(fwd.z, t, 0.02);
      l.upX.setTargetAtTime(up.x, t, 0.02);
      l.upY.setTargetAtTime(up.y, t, 0.02);
      l.upZ.setTargetAtTime(up.z, t, 0.02);
    } else {
      l.setPosition(p.x, p.y, p.z);
      l.setOrientation(fwd.x, fwd.y, fwd.z, up.x, up.y, up.z);
    }
  }

  setWind(speed: number): void {
    if (!this.wind || !this.ctx) return;
    const t = this.ctx.currentTime;
    const s = Math.min(1, speed / 60);
    this.wind.gain.gain.setTargetAtTime(s * s * 0.5, t, 0.2);
    this.wind.filter.frequency.setTargetAtTime(300 + speed * 18, t, 0.2);
  }

  /** Positional one-shot. */
  play(name: string, x: number, y: number, z: number, gain = 1, rate = 1, minInterval = 0.04): void {
    if (!this.ready || !this.ctx || gain <= 0.01) return;
    const now = this.ctx.currentTime;
    const last = this.lastPlay.get(name) ?? -1;
    if (now - last < minInterval) return;
    this.lastPlay.set(name, now);
    if (this.active > 28) return;
    const list = this.buffers.get(name);
    if (!list) return;
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = list[Math.floor(Math.random() * list.length)];
    src.playbackRate.value = rate * (0.92 + Math.random() * 0.16);
    const g = ctx.createGain();
    g.gain.value = Math.min(1.6, gain);
    const p = ctx.createPanner();
    p.panningModel = 'equalpower';
    p.distanceModel = 'inverse';
    p.refDistance = 6;
    p.rolloffFactor = 1.1;
    p.maxDistance = 600;
    if (p.positionX) {
      p.positionX.value = x;
      p.positionY.value = y;
      p.positionZ.value = z;
    } else p.setPosition(x, y, z);
    src.connect(g).connect(p).connect(this.sfxBus);
    this.active++;
    src.onended = () => {
      this.active--;
      src.disconnect();
      g.disconnect();
      p.disconnect();
    };
    src.start();
  }

  /** Non-positional UI sound. */
  playUI(name: string, gain = 0.6): void {
    if (!this.ready || !this.ctx) return;
    const list = this.buffers.get(name);
    if (!list) return;
    const src = this.ctx.createBufferSource();
    src.buffer = list[0];
    const g = this.ctx.createGain();
    g.gain.value = gain;
    src.connect(g).connect(this.sfxBus);
    src.start();
  }

  /** Looping positional sound built from a generator. */
  createLoop(kind: 'grinder' | 'motor'): LoopVoice | null {
    if (!this.ready || !this.ctx) return null;
    return new LoopVoice(this, kind);
  }

  createEngine(def: EngineDef): EngineVoice | null {
    if (!this.ready || !this.ctx) return null;
    return new EngineVoice(this, def);
  }

  createVehicleNoise(): VehicleNoise | null {
    if (!this.ready || !this.ctx) return null;
    return new VehicleNoise(this);
  }
}

function makePanner(ctx: AudioContext): PannerNode {
  const p = ctx.createPanner();
  p.panningModel = 'equalpower';
  p.distanceModel = 'inverse';
  p.refDistance = 7;
  p.rolloffFactor = 1;
  p.maxDistance = 800;
  return p;
}

function setPan(p: PannerNode, x: number, y: number, z: number, t: number): void {
  if (p.positionX) {
    p.positionX.setTargetAtTime(x, t, 0.02);
    p.positionY.setTargetAtTime(y, t, 0.02);
    p.positionZ.setTargetAtTime(z, t, 0.02);
  } else p.setPosition(x, y, z);
}

// ---------------------------------------------------------------------------

export class EngineVoice {
  private ctx: AudioContext;
  private oscA: OscillatorNode;
  private oscB: OscillatorNode;
  private oscC: OscillatorNode;
  private gA: GainNode;
  private gB: GainNode;
  private gC: GainNode;
  private noiseSrc: AudioBufferSourceNode;
  private noiseBp: BiquadFilterNode;
  private noiseG: GainNode;
  private shaper: WaveShaperNode;
  private lp: BiquadFilterNode;
  private out: GainNode;
  private pan: PannerNode;
  private turbo: OscillatorNode;
  private turboG: GainNode;
  private def: EngineDef;
  private prevThrottle = 0;
  private bov = 0;
  private engine: AudioEngine;

  constructor(engine: AudioEngine, def: EngineDef) {
    this.engine = engine;
    const ctx = engine.ctx!;
    this.ctx = ctx;
    this.def = def;
    const rough = def.roughness;
    const mkWave = (n: number, fall: number, seed: number) => {
      const real = new Float32Array(n), imag = new Float32Array(n);
      let s = seed;
      for (let k = 1; k < n; k++) {
        s = (s * 16807) % 2147483647;
        const rnd = s / 2147483647;
        const a = Math.pow(k, -fall) * (1 + (rnd - 0.5) * rough * 1.4);
        const ph = rnd * Math.PI * 2;
        real[k] = a * Math.cos(ph);
        imag[k] = a * Math.sin(ph);
      }
      return ctx.createPeriodicWave(real, imag, { disableNormalization: false });
    };
    this.oscA = ctx.createOscillator();
    this.oscA.setPeriodicWave(mkWave(40, 1.05, 1234 + def.cylinders));
    this.oscB = ctx.createOscillator();
    this.oscB.setPeriodicWave(mkWave(24, 0.8, 999 + def.cylinders * 7));
    this.oscC = ctx.createOscillator();
    this.oscC.type = 'sawtooth';
    this.gA = ctx.createGain();
    this.gB = ctx.createGain();
    this.gC = ctx.createGain();
    this.gA.gain.value = 0.5;
    this.gB.gain.value = 0.25 + rough * 0.4;
    this.gC.gain.value = 0.06;
    this.noiseSrc = ctx.createBufferSource();
    this.noiseSrc.buffer = engine.noiseBuffer('white');
    this.noiseSrc.loop = true;
    this.noiseBp = ctx.createBiquadFilter();
    this.noiseBp.type = 'bandpass';
    this.noiseBp.Q.value = 1.2;
    this.noiseG = ctx.createGain();
    this.noiseG.gain.value = 0.05;
    this.shaper = ctx.createWaveShaper();
    this.shaper.curve = shaperCurve(2.2 + rough * 2);
    this.shaper.oversample = '2x';
    this.lp = ctx.createBiquadFilter();
    this.lp.type = 'lowpass';
    this.lp.Q.value = 0.9;
    this.out = ctx.createGain();
    this.out.gain.value = 0;
    this.pan = makePanner(ctx);
    const mix = ctx.createGain();
    mix.gain.value = 0.6;
    this.oscA.connect(this.gA).connect(mix);
    this.oscB.connect(this.gB).connect(mix);
    this.oscC.connect(this.gC).connect(mix);
    this.noiseSrc.connect(this.noiseBp).connect(this.noiseG).connect(mix);
    mix.connect(this.shaper).connect(this.lp).connect(this.out).connect(this.pan).connect(engine.engineOut!);
    // turbo whine
    this.turbo = ctx.createOscillator();
    this.turbo.type = 'sine';
    this.turboG = ctx.createGain();
    this.turboG.gain.value = 0;
    this.turbo.connect(this.turboG).connect(this.pan);
    const t = ctx.currentTime;
    for (const o of [this.oscA, this.oscB, this.oscC, this.turbo]) o.start(t);
    this.noiseSrc.start(t);
  }

  update(rpm: number, throttle: number, running: boolean, misfire: boolean, x: number, y: number, z: number, near: boolean): void {
    const t = this.ctx.currentTime;
    const d = this.def;
    const f = Math.max(8, (rpm / 60) * (d.cylinders / 2));
    const k = 0.012;
    this.oscA.frequency.setTargetAtTime(f, t, k);
    this.oscB.frequency.setTargetAtTime(f * 0.5 * (1 + d.roughness * 0.004), t, k);
    this.oscC.frequency.setTargetAtTime(f * 2, t, k);
    this.noiseBp.frequency.setTargetAtTime(Math.min(8000, f * 3.5), t, k);
    const load = running ? throttle : 0;
    const rpmN = rpm / d.redline;
    this.lp.frequency.setTargetAtTime(300 + f * 4 + load * 2400 + rpmN * 900, t, 0.03);
    this.noiseG.gain.setTargetAtTime(0.03 + load * 0.12, t, 0.05);
    let g = running ? 0.32 + load * 0.55 + rpmN * 0.25 : rpm > 100 ? 0.15 * (rpm / 800) : 0;
    if (misfire) g *= 0.25;
    if (!near) g *= 0.8;
    this.out.gain.setTargetAtTime(g, t, misfire ? 0.005 : 0.03);
    // turbo
    if (d.forcedInduction > 0) {
      const boost = running ? Math.max(0, rpmN - 0.25) * load : 0;
      this.turbo.frequency.setTargetAtTime(2500 + rpm * 1.6, t, 0.1);
      this.turboG.gain.setTargetAtTime(boost * 0.05 * d.forcedInduction, t, 0.15);
      if (this.prevThrottle > 0.6 && throttle < 0.15 && rpm > d.redline * 0.45) this.bov = 1;
    }
    if (this.bov > 0) {
      this.engine.play('hiss', x, y, z, 0.5 * d.forcedInduction, 1.4, 0.4);
      this.bov = 0;
    }
    this.prevThrottle = throttle;
    setPan(this.pan, x, y, z, t);
  }

  dispose(): void {
    const t = this.ctx.currentTime;
    this.out.gain.setTargetAtTime(0, t, 0.05);
    setTimeout(() => {
      for (const o of [this.oscA, this.oscB, this.oscC, this.turbo]) o.stop();
      this.noiseSrc.stop();
      this.pan.disconnect();
    }, 300);
  }
}

function shaperCurve(drive: number): Float32Array<ArrayBuffer> {
  const n = 1024;
  const c = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * 2 - 1;
    c[i] = Math.tanh(x * drive) / Math.tanh(drive);
  }
  return c;
}

// ---------------------------------------------------------------------------
// Tire squeal, gravel roll, scraping and road rumble for one vehicle

export class VehicleNoise {
  private ctx: AudioContext;
  private squealG: GainNode;
  private squealBp: BiquadFilterNode;
  private squealOsc: OscillatorNode;
  private gravelG: GainNode;
  private scrapeG: GainNode;
  private scrapeBp: BiquadFilterNode;
  private roadG: GainNode;
  private roadLp: BiquadFilterNode;
  private pan: PannerNode;
  private srcs: AudioScheduledSourceNode[] = [];

  constructor(engine: AudioEngine) {
    const ctx = engine.ctx!;
    this.ctx = ctx;
    this.pan = makePanner(ctx);
    this.pan.connect(engine.sfxOut!);
    const mk = (buf: AudioBuffer | null) => {
      const s = ctx.createBufferSource();
      s.buffer = buf;
      s.loop = true;
      s.loopStart = Math.random() * 2;
      this.srcs.push(s);
      return s;
    };
    // squeal: band-passed noise + wobbling tone
    const n1 = mk(engine.noiseBuffer('white'));
    this.squealBp = ctx.createBiquadFilter();
    this.squealBp.type = 'bandpass';
    this.squealBp.frequency.value = 1200;
    this.squealBp.Q.value = 3;
    this.squealG = ctx.createGain();
    this.squealG.gain.value = 0;
    this.squealOsc = ctx.createOscillator();
    this.squealOsc.type = 'triangle';
    this.squealOsc.frequency.value = 950;
    const oscG = ctx.createGain();
    oscG.gain.value = 0.12;
    n1.connect(this.squealBp).connect(this.squealG);
    this.squealOsc.connect(oscG).connect(this.squealG);
    this.squealG.connect(this.pan);
    this.srcs.push(this.squealOsc);
    // gravel
    const n2 = mk(engine.noiseBuffer('pink'));
    const gl = ctx.createBiquadFilter();
    gl.type = 'bandpass';
    gl.frequency.value = 700;
    gl.Q.value = 0.6;
    this.gravelG = ctx.createGain();
    this.gravelG.gain.value = 0;
    n2.connect(gl).connect(this.gravelG).connect(this.pan);
    // scrape
    const n3 = mk(engine.noiseBuffer('white'));
    this.scrapeBp = ctx.createBiquadFilter();
    this.scrapeBp.type = 'bandpass';
    this.scrapeBp.frequency.value = 3000;
    this.scrapeBp.Q.value = 4;
    this.scrapeG = ctx.createGain();
    this.scrapeG.gain.value = 0;
    n3.connect(this.scrapeBp).connect(this.scrapeG).connect(this.pan);
    // road rumble
    const n4 = mk(engine.noiseBuffer('brown'));
    this.roadLp = ctx.createBiquadFilter();
    this.roadLp.type = 'lowpass';
    this.roadLp.frequency.value = 200;
    this.roadG = ctx.createGain();
    this.roadG.gain.value = 0;
    n4.connect(this.roadLp).connect(this.roadG).connect(this.pan);
    for (const s of this.srcs) s.start();
  }

  update(squeal: number, gravel: number, scrape: number, speed: number, x: number, y: number, z: number): void {
    const t = this.ctx.currentTime;
    const sq = Math.min(1, squeal);
    this.squealG.gain.setTargetAtTime(sq * sq * 0.55, t, 0.04);
    this.squealBp.frequency.setTargetAtTime(1000 + sq * 700, t, 0.08);
    this.squealOsc.frequency.setTargetAtTime(850 + sq * 250 + Math.sin(t * 23) * 25, t, 0.02);
    this.gravelG.gain.setTargetAtTime(Math.min(0.6, gravel * 0.5), t, 0.08);
    this.scrapeG.gain.setTargetAtTime(Math.min(0.9, scrape), t, 0.03);
    this.scrapeBp.frequency.setTargetAtTime(2200 + Math.min(3000, speed * 80), t, 0.05);
    this.roadG.gain.setTargetAtTime(Math.min(0.35, speed * 0.008), t, 0.1);
    this.roadLp.frequency.setTargetAtTime(120 + speed * 6, t, 0.1);
    setPan(this.pan, x, y, z, t);
  }

  dispose(): void {
    this.squealG.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);
    setTimeout(() => {
      for (const s of this.srcs) {
        try {
          s.stop();
        } catch {
          /* already stopped */
        }
      }
      this.pan.disconnect();
    }, 200);
  }
}

// ---------------------------------------------------------------------------

export class LoopVoice {
  private ctx: AudioContext;
  private g: GainNode;
  private pan: PannerNode;
  private srcs: AudioScheduledSourceNode[] = [];
  private osc: OscillatorNode | null = null;

  constructor(engine: AudioEngine, kind: 'grinder' | 'motor') {
    const ctx = engine.ctx!;
    this.ctx = ctx;
    this.pan = makePanner(ctx);
    this.pan.refDistance = 10;
    this.pan.connect(engine.sfxOut!);
    this.g = ctx.createGain();
    this.g.gain.value = 0;
    this.g.connect(this.pan);
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = kind === 'grinder' ? 48 : 90;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 500;
    const og = ctx.createGain();
    og.gain.value = 0.35;
    osc.connect(lp).connect(og).connect(this.g);
    const n = ctx.createBufferSource();
    n.buffer = engine.noiseBuffer('brown');
    n.loop = true;
    const ng = ctx.createGain();
    ng.gain.value = 0.6;
    n.connect(ng).connect(this.g);
    this.srcs.push(osc, n);
    this.osc = osc;
    for (const s of this.srcs) s.start();
  }

  set(x: number, y: number, z: number, gain: number, rate = 1): void {
    const t = this.ctx.currentTime;
    this.g.gain.setTargetAtTime(gain, t, 0.08);
    if (this.osc) this.osc.frequency.setTargetAtTime(48 * rate, t, 0.1);
    setPan(this.pan, x, y, z, t);
  }

  stop(): void {
    this.g.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);
    setTimeout(() => {
      for (const s of this.srcs) {
        try {
          s.stop();
        } catch {
          /* noop */
        }
      }
      this.pan.disconnect();
    }, 200);
  }
}
